using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = JsonSerializerOptions.Default;

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<int[]> arrayMeta = options.GetTypeInfo<int[]>();
Console.WriteLine($"Typed metadata for int[]: {arrayMeta.Type.Name}");

// 2) Probe without throwing — TryGetTypeInfo
if (options.TryGetTypeInfo(typeof(string), out JsonTypeInfo? stringMeta))
{
    Console.WriteLine($"Found metadata for String: {stringMeta!.Type.Name}");
}
else
{
    Console.WriteLine("No metadata for String");
}

// Probe for a type that may NOT have metadata (custom resolver with nothing registered)
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver() // knows built-ins
};
empty.MakeReadOnly();

// This will succeed:
if (empty.TryGetTypeInfo(typeof(DateTime), out JsonTypeInfo? dtMeta))
    Console.WriteLine($"Found metadata for DateTime: {dtMeta!.Type.Name}");

// Now use a resolver that resolves nothing:
var noResolver = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty chain
};
noResolver.MakeReadOnly();

if (noResolver.TryGetTypeInfo(typeof(DateTime), out _))
    Console.WriteLine("Unexpectedly found DateTime metadata");
else
    Console.WriteLine("No metadata for DateTime (resolver is empty) — no exception thrown");

